#!/bin/sh
# The SFTP server the emulator reaches as 10.0.2.2:2022: the same rclone v1.68.2 serving the same
# directory server/root over SFTP, password authentication with an invented user and password, its
# host keys generated by rclone into server/sftp-cache (not the user's cache), its log in
# out/rclone-sftp.log.
#   sh server-sftp.sh start | stop
. "$(dirname "$0")/env.sh"
R="$D/server/rclone-dl/rclone"; ROOT="$D/server/root"; PID="$D/out/rclone-sftp.pid"
case "$1" in
  start)
    mkdir -p "$ROOT" "$D/server/sftp-cache"
    nohup "$R" serve sftp "$ROOT" --addr 0.0.0.0:2022 --user kpg --pass <invented> \
      --cache-dir "$D/server/sftp-cache" --dir-cache-time 0s --poll-interval 0 --log-file "$D/out/rclone-sftp.log" -v >/dev/null 2>&1 &
    echo $! > "$PID"; sleep 3
    echo "sftp server started ($(cat "$PID")): $(ss -ltn 2>/dev/null | grep -c ':2022 ') listener(s) on 2022"
    ;;
  stop)
    [ -f "$PID" ] && kill "$(cat "$PID")" 2>/dev/null; rm -f "$PID"; sleep 1; echo "sftp server stopped"
    ;;
esac
